// Package integration runs the conformance suite against a real
// Zipkin (docker/compose.yml). Factories live in factories_test.go.
package integration

import (
	"bufio"
	"os"
	"strings"
	"testing"

	"github.com/grow-codes-packages/zipkin/go/testkit"
)

// loadBootstrapEnv reads KEY=value lines written by the compose bootstrap
// service. Variables already set in the environment win.
func loadBootstrapEnv(t *testing.T, path string) {
	t.Helper()
	f, err := os.Open(path)
	if err != nil {
		return // optional
	}
	defer func() { _ = f.Close() }()
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		key, value, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		key = strings.TrimSpace(strings.TrimPrefix(key, "export "))
		if _, set := os.LookupEnv(key); !set {
			t.Setenv(key, strings.Trim(strings.TrimSpace(value), `"'`))
		}
	}
}

func scenariosDir() string {
	if dir := os.Getenv("GROW_CONFORMANCE_DIR"); dir != "" {
		return dir
	}
	return "../../conformance/scenarios"
}

func TestConformance(t *testing.T) {
	bootstrap := os.Getenv("GROW_BOOTSTRAP_ENV")
	if bootstrap == "" {
		bootstrap = "/bootstrap/env"
	}
	loadBootstrapEnv(t, bootstrap)
	if os.Getenv("GROW_ZIPKIN_URL") == "" {
		t.Skip("GROW_ZIPKIN_URL is not set; run through docker/compose.yml")
	}
	testkit.Run(t, scenariosDir(), testkit.Options{
		Categories:   categories(),
		Factories:    factories(t),
		Capabilities: capabilities,
		ServiceName:  "grow-conformance-go",
	})
}
